          setCurrentUser(newUser);
          setCurrentStep(2);

          showSuccess('🎉 Congratulations!', 'Your account has been successfully created.\n\nYou may now complete your dating profile.');
          setIsLoading(false);
          return;
        } else {
          const errorMsg = result?.message || 'Registration failed. Please try again.';
          setRegistrationError(errorMsg);
          addNotification('❌ ' + errorMsg, 'error');
          setIsLoading(false);
          return;
        }
      } catch (error) {
        console.error('Registration error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    // Step 3: Details Registration
    if (step === 3) {
      setIsLoading(true);
      try {
        const phone = currentUser?.phone || myPhone || '0712345678';
        const data = {
          education_level: formData.education_level,
          profession: formData.profession,
          marital_status: formData.marital_status,
          religion: formData.religion,
          ethnicity: formData.ethnicity
        };

        const result = await callApi(`/${phone}/complete-profile`, 'POST', data);

        if (result && result.status === 'success') {
          // Check if details were provided (all fields filled)
          const hasAllDetails = formData.education_level && formData.profession && 
                               formData.marital_status && formData.religion && formData.ethnicity;

          if (hasAllDetails) {
            setSystemResponseMessage(SYSTEM_MESSAGES.detailsSuccess);
          } else {
            setSystemResponseMessage(SYSTEM_MESSAGES.detailsNotProvided);
          }
          setShowSystemResponse(true);

          setCompletedSteps(prev => new Set([...prev, 2]));
          addNotification('✅ Profile completed!');

          // Update current user
          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              education: formData.education_level,
              profession: formData.profession,
              marital_status: formData.marital_status,
              religion: formData.religion,
              ethnicity: formData.ethnicity
